import '../../style/support.css'
import axios from 'axios';
import { jsPDF } from 'jspdf';
import QRCode from 'qrcode';
import Success from './Success';
import React, { useState } from 'react';
export default function Reserver() {
    const [formData, setFormData] = useState({
        name: '',
        phone: '',
        message: '',
        date: ''
    });

    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value,
        });
    }


    const [creationSuccess, setCreationSuccess] = useState(false);
    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const response = await axios.post('http://localhost:8086/rendezvous', formData)
            console.log('Réservation réussie:', response.data);
            const qrData = `Nom: ${response.data.nom}\nTéléphone: ${response.data.numero}\nDate: ${response.data.date}`;

            const qrCodeImageUrl = await QRCode.toDataURL(qrData);

            const logoBase64 = "data:image/png;base64,";


            const doc = new jsPDF();

            // Configuration des couleurs
            const primaryColor = [46, 125, 50]; // Vert principal
            const secondaryColor = [76, 175, 80]; // Vert secondaire
            const darkGray = [66, 66, 66];
            const lightGray = [245, 245, 245];
            const white = [255, 255, 255];

            // === HEADER AVEC BACKGROUND ===
            // Fond coloré pour l'en-tête
            doc.setFillColor(...primaryColor);
            doc.rect(0, 0, 210, 35, 'F');

            // Logo (si disponible)
            if (logoBase64) {
                doc.addImage(logoBase64, 'PNG', 15, 8, 30, 18);
            }

            // Titre principal - Style gras
            doc.setTextColor(...white);
            doc.setFontSize(20);
            doc.setFont("helvetica", "bold");
            doc.text("AL-QUDS LABORATOIRE", 55, 18);

            // Slogan
            doc.setFontSize(11);
            doc.setFont("helvetica", "normal");
            doc.text("Votre sante, notre priorite", 55, 26);

            // === INFORMATIONS DE CONTACT ===
            doc.setTextColor(...darkGray);
            doc.setFontSize(9);
            doc.setFont("helvetica", "normal");

            // Barre de séparation
            doc.setFillColor(...lightGray);
            doc.rect(0, 35, 210, 20, 'F');

            const contactY = 42;
            doc.text("• Adresse: 123 rue de la Sante, Casablanca", 15, contactY);
            doc.text("• Tel: +212 6 1234 5678", 15, contactY + 4);
            doc.text("• Email: contact@alqudslab.com", 15, contactY + 8);
            doc.text("• Site web: https://alqudslab.com", 15, contactY + 12);

            // === TITRE PRINCIPAL DU TICKET ===
            doc.setTextColor(...primaryColor);
            doc.setFontSize(18);
            doc.setFont("helvetica", "bold");
            doc.text("TICKET DE RÉSERVATION", 15, 70);

            // Ligne de séparation sous le titre
            doc.setDrawColor(...primaryColor);
            doc.setLineWidth(1);
            doc.line(15, 74, 195, 74);

            // === INFORMATIONS DU RENDEZ-VOUS ===
            const infoStartY = 85;
            const lineHeight = 8;

            // Conteneur avec bordure pour les informations
            doc.setDrawColor(...lightGray);
            doc.setLineWidth(0.5);
            doc.rect(15, infoStartY - 5, 120, 50, 'S');

            // Titre section
            doc.setTextColor(...primaryColor);
            doc.setFontSize(14);
            doc.setFont("helvetica", "bold");
            doc.text("Informations du Patient", 20, infoStartY);

            // Détails du rendez-vous
            doc.setTextColor(...darkGray);
            doc.setFontSize(11);
            doc.setFont("helvetica", "normal");

            // Nom avec style
            doc.setFont("helvetica", "bold");
            doc.text("Nom:", 20, infoStartY + 10);
            doc.setFont("helvetica", "normal");
            doc.text(response.data.nom, 45, infoStartY + 10);

            // Téléphone
            doc.setFont("helvetica", "bold");
            doc.text("Téléphone:", 20, infoStartY + 18);
            doc.setFont("helvetica", "normal");
            doc.text(response.data.numero, 45, infoStartY + 18);

            // Date
            doc.setFont("helvetica", "bold");
            doc.text("Date:", 20, infoStartY + 26);
            doc.setFont("helvetica", "normal");
            doc.text(response.data.date, 45, infoStartY + 26);

            // Message (si présent)
            if (response.data.message) {
                doc.setFont("helvetica", "bold");
                doc.text("Message:", 20, infoStartY + 34);
                doc.setFont("helvetica", "normal");

                // Découper le message si trop long
                const splitMessage = doc.splitTextToSize(response.data.message, 80);
                doc.text(splitMessage, 45, infoStartY + 34);
            }

            // === SECTION QR CODE ===
            // Conteneur pour le QR code
            doc.setFillColor(...lightGray);
            doc.rect(145, infoStartY - 5, 50, 50, 'F');

            // Bordure du QR code
            doc.setDrawColor(...primaryColor);
            doc.setLineWidth(1);
            doc.rect(145, infoStartY - 5, 50, 50, 'S');

            // QR Code
            doc.addImage(qrCodeImageUrl, 'PNG', 155, infoStartY + 5, 30, 30);

            // Label sous le QR code
            doc.setTextColor(...darkGray);
            doc.setFontSize(8);
            doc.setFont("helvetica", "normal");
            doc.text("Scannez pour verification", 160, infoStartY + 42);

            const ticketNumber = `ALQ${Date.now().toString().slice(-8)}`;

            doc.setTextColor(...primaryColor);
            doc.setFontSize(12);
            doc.setFont("helvetica", "bold");
            doc.text(`N° Ticket: ${ticketNumber}`, 15, 155);
            doc.setTextColor(...darkGray);
            doc.setFontSize(10);
            doc.setFont("helvetica", "normal");
            doc.text("Veuillez presenter ce ticket lors de votre visite.", 15, 165);

            // === FOOTER ===
            doc.setFillColor(...primaryColor);
            doc.rect(0, 270, 210, 27, 'F');

            doc.setTextColor(...white);
            doc.setFontSize(10);
            doc.setFont("helvetica", "bold");
            doc.text("Merci de votre confiance", 105, 285, { align: 'center' });

            doc.setFontSize(8);
            doc.setFont("helvetica", "normal");
            doc.text("AL-QUDS LABORATOIRE - Votre partenaire santé", 105, 290, { align: 'center' });
            doc.save(`ticket_reservation_${ticketNumber}.pdf`);
            setCreationSuccess(true);

        } catch (error) {
            console.error('Erreur lors de l’envoi:', error);
            alert('Une erreur est survenue lors de la réservation.');
        }
    }

    return (
        <div className='w-full py-20'>
            <div className='w-11/12 mx-auto grid grid-cols-2 items-center'>
                <div className="">
                    <span className='text-sm font-mont font-semibold text-slate-700'>AL-QUDS LABORATOIRE</span>
                    <h1 className='text-6xl font-mont font-semibold text-slate-700 mt-8'><span className="text-red-500">Votre santé,</span> notre priorité</h1>
                    <p className='text-lg font-mont text-slate-500 mt-8'>Notre laboratoire propose des analyses médicales fiables et rapides. Consultez vos résultats en ligne et contactez-nous pour toute information complémentaire.</p>
                </div>
                <div className='p-10'>
                    <div className="bg-slate-100 shadow-xl rounded-lg p-6 font-mont">
                        <h2 className="text-2xl text-slate-700 font-semibold mb-4">Réserver</h2>
                        <form onSubmit={handleSubmit}>
                            <div className="mb-4">
                                <label className="text-lg font-medium text-slate-700">Nom</label>
                                <input
                                    name="nom"
                                    type="text"
                                    value={formData.nom}
                                    onChange={handleChange}
                                    className="bg-white w-full border border-gray-300 text-slate-900 text-lg font-mont rounded-lg outline-none py-2 px-4"
                                    placeholder="Nom ou identifiant patient"
                                    required
                                />
                            </div>
                            <div className="mb-4">
                                <label className="text-lg font-medium text-gray-700">Numéro</label>
                                <input
                                    name="numero"
                                    type="text"
                                    value={formData.numero}
                                    onChange={handleChange}
                                    className="bg-white w-full border border-gray-300 text-slate-900 text-lg font-mont rounded-lg outline-none py-2 px-4"
                                    placeholder="Votre numéro téléphone"
                                    required
                                />
                            </div>
                            <div className='mb-4'>
                                <label className="text-lg font-medium text-gray-700">Message</label>
                                <textarea
                                    name="message"
                                    value={formData.message}
                                    onChange={handleChange}
                                    className="bg-white w-full border border-gray-300 text-slate-400 text-lg font-mont rounded-lg outline-none py-2 px-4 h-32"
                                    placeholder="Votre message ou note"
                                ></textarea>
                            </div>
                            <div className="mb-4">
                                <label className="text-lg font-medium text-gray-700">Date de rendez-vous</label>
                                <input
                                    name="date"
                                    type="date"
                                    value={formData.date}
                                    onChange={handleChange}
                                    className="bg-white w-full border border-gray-300 text-slate-900 text-lg font-mont rounded-lg outline-none py-2 px-4"
                                    required
                                />
                            </div>
                            <button
                                type="submit"
                                className="w-full bg-red-500 text-white py-2 rounded-md hover:bg-red-600 transition duration-300"
                            >
                                Réserver
                            </button>
                        </form>
                    </div>
                </div>
            </div>
            {creationSuccess && <Success titre="La réservation du rendez-vous a été effectuée" message="Veuillez vous présenter le jour du rendez-vous avec le PDF de réservation. Merci." />}
        </div>
    );
}
